import json
from pathlib import Path
pages={p['page']:p['flat'] for p in map(json.loads,Path('out/index/pages.jsonl').read_text().splitlines())}
claims=[]
def c(id,statement,page,quote,conditions='',kind='FACT',reasoning=None,value=None):
 assert quote in pages[page],id
 x=dict(id=id,statement=statement,page=page,quote=quote,conditions=conditions,source='正文及表1' if page==4 else '正文',value=value,**{'class':kind})
 if reasoning:x['reasoning']=reasoning
 claims.append(x)
c('C1','作者将目标定位为中等规模的监督与无监督问题，并强调易用性、性能、文档和API一致性。',2,'Scikit-learn is a Python module integrating a wide range of state-of-the-art machine learning algorithms for medium-scale supervised and unsupervised problems.','2011年论文定位；不是对任意规模的性能承诺。')
c('C2','统一接口靠约定而非强制继承：estimator 的 fit 接受输入数据数组，监督任务可另给标签；监督估计器可用 predict；transformer（例如PCA）用 transform 返回变换后的数据。',3,'inheritance is not enforced; instead, code conventions provide a consistent interface. The central object is an estimator, that implements a fit method, accepting as arguments an input data array and, optionally, an array of labels for supervised problems. Supervised estimators, such as SVM classifiers, can implement a predict method. Some estimators, that we call transformers, for example, PCA, implement a transform method, returning modified input data.','并非每个估计器都提供所有方法；输入以NumPy数组组织。')
c('C3','score 被描述为随拟合优度增加而增大的评价，例如对数似然或负损失。交叉验证迭代器给出训练/测试索引对，支持K-fold、留一和分层交叉验证。',4,'may also provide a score method, which is an increasing evaluation of goodness of fit: a loglikelihood, or a negated loss function. The other important object is the cross-validation iterator, which provides pairs of train and test indices to split input data, for example K-fold, leave one out, or stratified cross-validation.','不同估计器的score不自动具有相同科学含义；这里不是表1的计时指标。')
c('C4','GridSearchCV 包装估计器，以交叉验证评估性能或选参，可选多核计算；fit 在指定参数网格中最大化底层score，随后把 predict、score、transform 委托给调优后的估计器。',4,'Scikit-learn can evaluate an estimator’s performance or select parameters using cross-validation, optionally distributing the computation to several cores. This is accomplished by wrapping an estimator in a GridSearchCV object, where the “CV” stands for “cross-validated”. During the call to fit, it selects the parameters on a specified parameter grid, maximizing a score (the score method of the underlying estimator). predict, score, or transform are then delegated to the tuned estimator.','2011年的设计说明；不是今日参数签名或默认值。')
c('C5','Pipeline 把多个transformer和一个估计器组成标准估计器，例如先降维再拟合；GridSearchCV 因而可调各步骤参数。',4,'Finally, a Pipeline object can combine several transformers and an estimator to create a combined estimator to, for example, apply dimension reduction before fitting. It behaves as a standard estimator, and GridSearchCV therefore tune the parameters of all steps.','支持组合与统一调参；本文未给完整课程平台或数据泄漏防护流程。')
c('C6','表1基准使用Madelon：4400个样本、500个属性；作者说它足够大，但多数算法仍可运行。',4,'We use the Madelon data set (Guyon et al., 2004), 4400 instances and 500 attributes, The data set is quite large, but small enough for most algorithms to run.','仅此基准规模，不能改称超大规模流数据。',value='4400; 500')
# 文本按列抽取；数值所在连续引文保留，并用PNG人工核对行列。
q=pages[4][pages[4].index('Support Vector Classification'):pages[4].index('may also provide')].strip()
c('C7','性能优势实例：Madelon上的Support Vector Classification，scikit-learn 5.2秒，mlpy 9.47秒，pybrain 17.5秒，pymvpa 11.52秒，mdp 40.48秒，shogun 5.63秒；该行scikit-learn时间最短。',4,q,'表1计时单位为秒；行列对应已用out/page4.png及page4-layout.txt人工复核。仅该实验，不是预测准确率、所有算法或今天版本的排名。',value='5.2; 9.47; 17.5; 11.52; 40.48; 5.63')
c('C8','不占优势的反例：同一Madelon基准，k-Means（9簇）scikit-learn 1.34秒，慢于mlpy 0.79秒和shogun 0.68秒；k-Nearest Neighbors为0.57秒，也略慢于pymvpa 0.56秒。',4,q,'表1；数值及算法/库归属依赖版面核对，机械字符串匹配本身不能验证行列归属或差异显著性；未报告误差条，近邻差异不宜解读为稳定优势。',value='9; 1.34; 0.79; 0.68; 0.57; 0.56')
c('C9','Elastic Net坐标下降在中等规模问题上与高度优化的Fortran glmnet处于同一性能量级，但超大问题受限，因为未用KKT条件定义活跃集。',5,'It achieves the same order of performance as the highly optimized Fortran version glmnet (Friedman et al., 2010) on medium-scale problems, but performance on very large problems is limited since we do not use the KKT conditions to define an active set.','紧接Elastic Net坐标下降说明；同量级不等于总是更快。')
c('C10','当时k-means为纯Python实现，NumPy数组操作需多遍扫描数据，限制其性能。',5,'scikit-learn’s k-means algorithm is implemented in pure Python. Its performance is limited by the fact that numpy’s array operations take multiple passes over data.','仅描述2011年文中实现，不据此声称今日k-means仍为纯Python。')
c('C11','online learning在结论中是面向大数据扩展的未来工作，不能把这句当作已实现超大规模在线训练的证据。',5,'Future work includes online learning, to scale to large data sets.','这是作者对未来方向的表述；也不由此反推每个组件当时都绝无增量能力。')
c('I1','课程平台在架构上适配；统一模型接口、预处理组合、网格选参与交叉验证的设计可借鉴，但落地需明确评价指标、数据分割和资源预算。',4,'Finally, a Pipeline object can combine several transformers and an estimator to create a combined estimator to, for example, apply dimension reduction before fitting. It behaves as a standard estimator, and GridSearchCV therefore tune the parameters of all steps.','用户给定中等规模、可装入内存的表格数据；未实际运行模型。',kind='INFERRED',reasoning='结合C1的规模定位与C2—C5的接口事实，推断这些抽象符合课程组织需求；论文没有验证本课程数据和部署环境，因此只能给有条件采用建议。应将需要学习参数的预处理纳入训练折内拟合，并留独立测试集或另设外层评估，避免调参分数直接充作最终泛化评价；这是工程建议，非论文已完成的实证。')
c('I2','“所有算法都最快且适合超大规模在线训练”不可作为这篇论文的结论采用。',5,'Future work includes online learning, to scale to large data sets.','评价的是所提证据主张，而非断言软件对所有大数据任务均不可用。',kind='INFERRED',reasoning='C8存在反例，足以否定表1支持全称速度优势；C6基准规模有限，C9—C10承认性能局限，C11又把在线学习列为未来工作。因此该强主张超出了论文证据。')
claims.append(dict(id='U1',**{'class':'UNKNOWN'},statement='今天的版本接口、默认行为、算法实现、在线训练支持范围及在课程机器上的性能尚未确定。',value=None,absence_probe=['online learning','k-means','GridSearchCV','release','benchmark'],search_scope='所供2011年六页PDF正文及参考文献；无当前版本文档、仓库快照、基准代码或运行结果。',reasoning='阅读全文及命中上下文可知它记录的是历史设计和实验；即使命中同名组件，也不能回答当前版本状态。未联网且未运行模型，故保留缺口。'))
claims.append(dict(id='U2',**{'class':'UNKNOWN'},statement='表1的完整可复现配置和结果可比性无法从所供正文确定。',value=None,absence_probe=['Table 1','hardware','tolerance','seconds','github'],search_scope='所供六页PDF，未访问文中外部链接。',reasoning='表1及邻文给出数据规模、算法、库和秒数，并提及外部基准；所供正文不足以确定各库版本、硬件、线程、超参数、停止准则、计时是否含数据准备、重复次数及方差。不能据此认定严格同精度同预算或稳定的速度比。'))
doc=dict(paper=dict(title='Scikit-learn: Machine Learning in Python',doi='',question='2011年论文对中等规模内存表格数据课程平台的工程适配，以及速度与在线训练强主张的证据边界',limitations_of_this_audit=['材料仅为INPUT/paper.pdf，6页（印刷页2825—2830），未提供补充材料、代码快照和当前版本文档。页数符合任务说明，但索引本身不证明来源完整性。','未联网、未训练、未复现。PDF文本可读；表1另经渲染图像核对行列。','初次尝试读取out/index/pages.json失败：该脚本实际输出pages.jsonl；已改正读取路径。保存操作记录，未隐去此失败。']),claims=claims,parameters=[],derivations=[],coverage=[],transfer=[],verdict_overall='需改造',gaps=[],boundaries=['课程平台的总体判断是有条件采用；“需改造”指完善工程与教学评估流程，不表示已发现必须修改库源码。','事实限于2011年文章；推断基于用户给定数据条件；UNKNOWN只描述所供材料未能解决的事项。','机械通过只证明字面定位和数值出现，不证明科学含义、基准公平性或材料覆盖充分。'])
for item,ids in [('estimator/transformer与score接口',['C2','C3']),('交叉验证、GridSearchCV、Pipeline',['C3','C4','C5']),('表1优势与反例、规模及单位',['C6','C7','C8']),('Elastic Net与k-means局限',['C9','C10']),('online learning的历史状态',['C11','I2']),('课程适配与版本边界',['C1','I1','U1','U2'])]:doc['coverage'].append(dict(item=item,status='covered',claim_ids=ids))
for step,verdict,ids,needs in [('统一接口与组合设计','可直接用',['C2','C3','C4','C5'],'可直接借鉴抽象；实现前核对拟锁定版本的官方API。'),('课程平台实现与评估','需改造',['C1','I1','U1'],'确认缺失值、类别编码、缩放需求；按任务选择指标与分割策略；训练折内拟合预处理；控制网格和并行内存，保留独立评估。'),('当前版本的具体性能与实现','信息不足',['U1','U2'],'补读锁定版本官方文档、发布说明及源代码，并另行授权后在课程硬件和代表性数据上比较时间、内存与预测质量。'),('把本文用作所有算法最快及超大规模在线训练证据','不可用',['C8','C9','C10','C11','I2'],'撤回该证据主张；若确需流式或超大数据，另查当前增量接口、支持算法与内存限制。')]:doc['transfer'].append(dict(step=step,verdict=verdict,because=ids,needs=needs))
for gap,impact,close in [('当前版本未提供','无法承诺今天的API和性能','取得并锁定目标版本的官方用户指南、API、版本发布说明；核查Pipeline、GridSearchCV及相关估计器源码'),('原始基准配置缺失','不能外推绝对耗时或作公平排名','取得论文对应历史benchmark脚本与环境记录，确认版本、硬件、线程、超参数、停止条件、计时范围和重复试验'),('课程实际数据与运行预算未验证','平台选型仍需工程验收','核对数据大小、稀疏性、类别/缺失值、分组或时间结构和评价目标；另行执行代表性验收，记录峰值内存和全网格耗时')]:doc['gaps'].append(dict(gap=gap,impact=impact,close=close))
Path('out/claims.json').write_text(json.dumps(doc,ensure_ascii=False,indent=2)+'\n')
